// Project folders on disk: <data>/projects/<user id>/<project id>/. Both ids are generated by the hub and checked
// against ID_PATTERN before they become a path; a project's name is a label in the store and never touches the disk.
import { randomBytes } from "node:crypto"
import { createWriteStream } from "node:fs"
import { lstat, mkdir, readdir, rename } from "node:fs/promises"
import { dirname, join } from "node:path"
import { Readable, type Writable } from "node:stream"
import { resolveInRoot } from "../core/workspace.js"
import { checkNoLinks, isInside, measureTree, removeWhatWeCan, shareTree, shareWithWorkspaceGroup, readListed, removeTree, usageOf, walkProject, type Measured, type SafeFile } from "./safe-files.js"
import { ID_PATTERN } from "./secrets.js"
import { extractEntry, StreamZipWriter, type ZipOnDisk } from "./zip-stream.js"

/** Leftovers of an interrupted atomic write (`writeFileAtomic`): `<name>.<pid>.<hex>.tmp`. Never part of a download. */
const ATOMIC_LEFTOVER = /\.\d+\.[0-9a-f]{8}\.tmp$/
/** The list of entries a download could not include, added to the zip when there are any. */
export const SKIPPED_FILE = "SKIPPED.txt"

function checkId(id: string): string {
  if (!ID_PATTERN.test(id)) throw new Error("Not a generated id")
  return id
}

export type ProjectFile = SafeFile

export class ProjectFiles {
  readonly root: string
  /** Uploads in progress, under the data directory. */
  readonly uploads: string

  constructor(dataDir: string) {
    this.root = join(dataDir, "projects")
    this.uploads = join(dataDir, "uploads")
  }

  userDir(userId: string): string {
    return join(this.root, checkId(userId))
  }

  projectDir(userId: string, projectId: string): string {
    return join(this.userDir(userId), checkId(projectId))
  }

  /** The gid of the group the hub shares with container workspaces; project folders get it with mode 2770. */
  workspaceGroup: number | undefined = undefined

  async create(userId: string, projectId: string): Promise<string> {
    const dir = this.projectDir(userId, projectId)
    await mkdir(dir, { recursive: true, mode: 0o700 })
    await this.share(dir)
    return dir
  }

  /** The project folder itself gets the workspace group and mode 2770 (nothing else under the data directory does). */
  async share(dir: string): Promise<void> {
    if (this.workspaceGroup !== undefined) await shareWithWorkspaceGroup(dir, this.workspaceGroup)
  }

  /** Where removed folders go first, out of every mount, before they are removed. */
  get trash(): string {
    return join(this.root, "..", "trash")
  }

  /**
   * Moves a folder (a project's, or a user's) into the trash, out of every mount, under a name that says whose it is;
   * the trash still counts toward that user's usage until it is really gone. Undefined when there was nothing to move.
   * Only project-folders.ts calls this, with the project blocked and its container confirmed gone.
   */
  async moveToTrash(userId: string, dir: string): Promise<string | undefined> {
    await mkdir(this.trash, { recursive: true, mode: 0o700 })
    const parked = join(this.trash, `${checkId(userId)}-${randomBytes(16).toString("hex")}`)
    try {
      await rename(dir, parked) // removal: out of the projects tree, called only from project-folders.ts
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined
      throw error
    }
    return parked
  }

  /**
   * Before the cleaning container runs on a folder in the trash: what the hub owns there gets the workspace group, so
   * the container (the workspace's uid) can enter and remove it too. No container sees the trash meanwhile.
   */
  async openParked(parked: string): Promise<void> {
    this.checkParked(parked)
    if (this.workspaceGroup !== undefined) await shareTree(parked, this.workspaceGroup)
  }

  /** Removes what the hub can of a folder in the trash; true when it is gone (with the process runner, it all is). */
  async removeParked(parked: string): Promise<boolean> {
    this.checkParked(parked)
    if (this.workspaceGroup === undefined) {
      await removeTree(parked) // removal: trash only
      return true
    }
    return removeWhatWeCan(parked) // removal: trash only
  }

  private checkParked(parked: string): void {
    if (!isInside(this.trash, parked) || parked === this.trash) throw new Error("Not a folder in the trash")
  }

  /** Gives what the hub owns in a project the workspace group again; only while its workspace cannot run. */
  async repair(dir: string): Promise<void> {
    if (this.workspaceGroup !== undefined) await shareTree(dir, this.workspaceGroup)
  }

  /** The folders in the trash, with the user each belongs to. */
  async allTrash(): Promise<{ userId: string; path: string }[]> {
    const names = await readdir(this.trash).catch(() => [] as string[])
    return names.flatMap((name) => {
      const match = /^([0-9a-f]{32})-[0-9a-f]{32}$/.exec(name)
      return match ? [{ userId: match[1] as string, path: join(this.trash, name) }] : []
    })
  }

  /** The regular files under a folder; links and special files are skipped, never followed (safe-files.ts). */
  async list(dir: string, note: (relativePath: string, why: string) => void = this.note): Promise<ProjectFile[]> {
    return walkProject(dir, note)
  }

  /** Where skipped links and special files are noted; server side only. */
  note: (relativePath: string, why: string) => void = () => undefined

  /**
   * Bytes the user's projects take on disk (regular files, each at its full size), with lstat only, so it is safe
   * while workspaces run; a measurement that fails throws (callers that guard the quota treat that as over).
   */
  async usage(userId: string): Promise<number> {
    return usageOf(this.userDir(userId))
  }

  /** The user's measurement, or why there is none. */
  async measureUser(userId: string, limits: { maxEntries?: number; maxMs?: number } = {}): Promise<Measured> {
    // The user's trash counts until it is really gone (a removal that failed keeps the quota charged).
    const trash = (await this.allTrash()).filter((entry) => entry.userId === userId).map((entry) => entry.path)
    let bytes = 0
    for (const dir of [this.userDir(userId), ...trash]) {
      const measured = await measureTree(dir, limits)
      if ("failed" in measured) return measured
      bytes += measured.bytes
    }
    return { bytes }
  }

  /** Bytes one project takes on disk (lstat only). */
  async projectUsage(userId: string, projectId: string): Promise<Measured> {
    return measureTree(this.projectDir(userId, projectId))
  }

  /**
   * Streams the project as a zip to `out`, file by file, each deflated as it is read: no whole file, let alone the
   * whole project, is held in memory. Leftover temporary files of interrupted writes are left out; a file swapped for
   * anything else after it was listed (each is opened without following links and checked) ends the download.
   */
  async download(userId: string, projectId: string, out: Writable): Promise<void> {
    const dir = this.projectDir(userId, projectId)
    const zip = new StreamZipWriter(out)
    // Entries the hub may not read (a workspace made them owner-only) are listed in SKIPPED.txt, never silently left out.
    const skipped: string[] = []
    const files = await this.list(dir, (path, why) => {
      this.note(path, why)
      skipped.push(`${path}: ${why}`)
    })
    for (const file of files) {
      if (ATOMIC_LEFTOVER.test(file.name)) continue
      let source
      try {
        source = await readListed(dir, file)
      } catch (error) {
        const code = (error as NodeJS.ErrnoException).code
        this.note(file.name, `not read: ${(error as Error).message}`)
        if (code === "EACCES" || code === "EPERM") {
          skipped.push(`${file.name}: could not be read (permission denied)`)
          continue
        }
        // A file gone or swapped mid-download ends the download (an archive missing it would look complete).
        throw error
      }
      await zip.addFile(file.name, source, file.modified)
    }
    if (skipped.length > 0) {
      const text = `These entries were not included:\n${skipped.map((line) => `- ${line}`).join("\n")}\n`
      await zip.addFile(SKIPPED_FILE, Readable.from([Buffer.from(text, "utf8")]), new Date())
    }
    await zip.finish()
  }

  /** The file an upload in progress is written to (never over an existing one); a seam for tests of a failing disk. */
  uploadSink(path: string): Writable {
    return createWriteStream(path, { flags: "wx", mode: 0o600 })
  }

  /** A path for an upload in progress, under the data directory (never under a project). */
  async uploadPath(): Promise<string> {
    await mkdir(this.uploads, { recursive: true, mode: 0o700 })
    return join(this.uploads, `upload-${randomBytes(16).toString("hex")}.zip`)
  }

  /**
   * Inflates a checked archive into a NEW staging folder under the uploads folder, entry by entry, each through the
   * core's in-root check and never over an existing file. The staging folder is not a project: no row names it and no
   * container can mount it. On failure it is removed (no container ever saw it) and the error is thrown.
   */
  async unpackStaged(zip: ZipOnDisk): Promise<string> {
    await mkdir(this.uploads, { recursive: true, mode: 0o700 })
    const dir = join(this.uploads, `stage-${randomBytes(16).toString("hex")}`)
    await mkdir(dir, { mode: 0o700 })
    try {
      for (const entry of zip.files) {
        const path = resolveInRoot(dir, entry.name)
        await checkNoLinks(dir, dirname(path))
        await mkdir(dirname(path), { recursive: true, mode: 0o700 })
        await extractEntry(zip, entry, path)
      }
      // While still in staging, where no container can see it: everything gets the workspace group (folders 2770,
      // files 0660), so the workspace (another uid) can use it and remove it later.
      if (this.workspaceGroup !== undefined) await shareTree(dir, this.workspaceGroup)
      return dir
    } catch (error) {
      await removeTree(dir) // removal: uploads only
      throw error
    }
  }

  /** Moves a finished staging folder into place as the project's folder with one rename (refused if it exists). */
  async place(staged: string, userId: string, projectId: string): Promise<void> {
    await mkdir(this.userDir(userId), { recursive: true, mode: 0o700 })
    await rename(staged, this.projectDir(userId, projectId)) // removal: into the projects tree, never out of it
    await this.share(this.projectDir(userId, projectId))
  }

  /** Removes a staging folder that was never placed (only ever under the uploads folder). */
  async discard(staged: string): Promise<void> {
    if (!isInside(this.uploads, staged) || staged === this.uploads) throw new Error("Not a staging folder")
    await removeTree(staged) // removal: uploads only
  }

  /** Staging folders older than `ms`, left by an upload interrupted by a crash. */
  async staleStaging(ms: number, now = Date.now()): Promise<string[]> {
    const names = await readdir(this.uploads).catch(() => [] as string[])
    const stale: string[] = []
    for (const name of names.filter((entry) => /^stage-[0-9a-f]{32}$/.test(entry))) {
      const info = await lstat(join(this.uploads, name)).catch(() => undefined)
      if (info?.isDirectory() && now - info.mtimeMs > ms) stale.push(join(this.uploads, name))
    }
    return stale
  }

  /** Whether the folder's last change (ctime: also renames and mode changes) is older than `ms`. */
  async olderThan(dir: string, ms: number, now = Date.now()): Promise<boolean> {
    const info = await lstat(dir).catch(() => undefined)
    return info !== undefined && now - info.ctimeMs > ms
  }

  /** Folders under the projects tree, as (user, project) ids, for the orphan sweep; ids not of our shape are ignored. */
  async projectFolders(): Promise<{ userId: string; projectId: string }[]> {
    const found: { userId: string; projectId: string }[] = []
    for (const userId of (await readdir(this.root).catch(() => [] as string[])).filter((name) => ID_PATTERN.test(name))) {
      for (const projectId of (await readdir(join(this.root, userId)).catch(() => [] as string[])).filter((name) => ID_PATTERN.test(name))) found.push({ userId, projectId })
    }
    return found
  }
}
